(function(){
  function b64ToBuf(b64) {
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
  }
  function makePart(data) {
    return {
      center: data.center,
      getPositions: () => new Float32Array(b64ToBuf(data.pos)),
      getIndices: () => new Uint16Array(b64ToBuf(data.ind)),
      getColors: () => new Float32Array(b64ToBuf(data.col)),
      vertexCount: data.v_count,
      indexCount: data.i_count
    };
  }
  window.GLOOPI_ASSETS = {
    full: {
      getPositions: () => new Float32Array(b64ToBuf("")),
      getIndices: () => new Uint16Array(b64ToBuf("")),
      getColors: () => new Float32Array(b64ToBuf("")),
      vertexCount: 10834,
      indexCount: 65118
    },
    parts: {
      lower: makePart({"center": [0.0, -0.55, 0.0], "pos": "", "ind": "", "col": "", "v_count": 7210, "i_count": 42867}),
      head: makePart({"center": [0.0, 0.15, 0.0], "pos": "", "ind": "", "col": "", "v_count": 3309, "i_count": 19326}),
      antenna: makePart({"center": [0.0, 0.72, 0.0], "pos": "", "ind": "", "col": "", "v_count": 503, "i_count": 2925})
    }
  };
})();